report[$k]??[]) as $item):?><li><?=e((string)$item)?></li><?php endforeach;?></ul><?php endforeach;?><small>Analyse indicative à relire. Le score classique reste indépendant.</small></div></details></td></tr><?php endif;?><?php endforeach;?></tbody></table></div></div><div id="research-kanban" class="research-kanban" hidden><?php foreach(['to_review'=>'À étudier','to_apply'=>'En préparation','archived'=>'Archivée'] as $researchStatus=>$researchLabel):?><section class="research-lane research-lane-<?=e($researchStatus)?>"><h3><?=e($researchLabel)?> <span><?=count(array_filter($offers,static fn($o)=>$o['status']===$researchStatus))?></span></h3><?php foreach($offers as $o):if($o['status']!==$researchStatus)continue;?><article class="research-card"><strong><?=e($o['title'])?></strong><small><?=e($o['company']??'')?> · <?=e($o['city']??'')?></small><?php if($o['match_score']!==null):?><span class="match-pill"><?=(int)$o['match_score']?> %</span><?php endif;?><div class="record-actions"><?php if($researchStatus!=='to_apply'):?><form method="post"><input type="hidden" name="csrf" value="<?=e($_SESSION['csrf'])?>"><input type="hidden" name="action" value="offer_stage"><input type="hidden" name="id" value="<?=(int)$o['id']?>"><input type="hidden" name="stage" value="to_apply"><input type="hidden" name="space_id" value="<?=$currentSpace?>"><button class="small-action">Créer la candidature</button></form><?php else:?><a class="small-action" href="<?=e(url('applications').(!empty($o['active_application_id'])?'&id='.(int)$o['active_application_id']:''))?>">Continuer la candidature →</a><?php endif;?><a class="small-action" href="<?=e(url('searches').'&space='.$currentSpace.'&edit_offer='.$o['id'])?>">Modifier</a></div><?php if(isset($offerAiReports[(int)$o['id']])):$kanbanAi=$offerAiReports[(int)$o['id']];?><details><summary>Analyse IA</summary><p><?=e((string)($kanbanAi['report']['summary']??''))?></p></details><?php endif;?></article><?php endforeach;?></section><?php endforeach;?></div><?php if(!$offers):?><div class="empty">Aucune offre enregistrée dans cet espace.</div><?php endif;?></section><script>(function(){const table=document.getElementById('research-table'),board=document.getElementById('research-kanban'),bt=document.getElementById('research-show-table'),bk=document.getElementById('research-show-kanban');if(!table||!board||!bt||!bk)return;function show(kanban){table.hidden=kanban;board.hidden=!kanban;bt.setAttribute('aria-pressed',String(!kanban));bk.setAttribute('aria-pressed',String(kanban));}bt.addEventListener('click',()=>show(false));bk.addEventListener('click',()=>show(true));show(false);})();</script>
